import math
import unittest

from solution import scale_readings


class ScaleReadingsTests(unittest.TestCase):
    def test_scaling_preserves_order_and_endpoints(self):
        values = [10, 20, 15, -10]
        result = scale_readings(values)
        self.assertEqual(result, [2.0 / 3.0, 1.0, 5.0 / 6.0, 0.0])
        self.assertTrue(all(isinstance(value, float) for value in result))

    def test_negative_range_uses_difference_not_sum(self):
        self.assertEqual(scale_readings([-5, -3, -1]), [0.0, 0.5, 1.0])

    def test_empty_and_equal_values(self):
        self.assertEqual(scale_readings([]), [])
        self.assertEqual(scale_readings([7, 7, 7]), [0.0, 0.0, 0.0])
        self.assertEqual(scale_readings([2.5]), [0.0])

    def test_mixed_integer_and_float_values(self):
        self.assertEqual(scale_readings([0, 0.5, 1]), [0.0, 0.5, 1.0])

    def test_wrong_types_raise_type_error(self):
        for value in (None, (), "1,2", {1, 2}):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    scale_readings(value)
        for values in ([1, True], [False], [1, "2"], [None], [1, object()]):
            with self.subTest(values=values):
                with self.assertRaises(TypeError):
                    scale_readings(values)

    def test_non_finite_values_raise_value_error(self):
        for value in (math.inf, -math.inf, math.nan):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    scale_readings([0.0, value])

    def test_input_is_not_mutated_and_result_is_new(self):
        values = [3, 1, 2]
        original = values.copy()
        result = scale_readings(values)
        self.assertEqual(values, original)
        self.assertIsNot(result, values)


if __name__ == "__main__":
    unittest.main()

